package main

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/signal"
	"runtime"
	"strings"
	"syscall"
	"time"

	"github.com/entireio/cli/cmd/entire/cli"
	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/entireio/cli/internal/procsignal"

	"github.com/spf13/cobra"
)

func main() {
	// Resolve version/commit from build info before anything reads them.
	versioninfo.Load()

	// Create context that cancels on interrupt
	ctx, cancel := context.WithCancel(context.Background())

	// Memoize this process's .git/config remote reads. The checkpoint sync
	// election re-runs per call by design and each run shells out to git for the
	// same two answers; one command can elect several times. Answers are
	// partitioned per git working directory, so a command walking several repos
	// stays correct. `entire repo mirror use` invalidates after re-pointing a
	// remote, and `entire mcp` narrows this to one window per request.
	ctx = strategy.WithGitRemoteCache(ctx)

	// Handle interrupt signals
	sigChan := make(chan os.Signal, 1)
	signals := []os.Signal{os.Interrupt}
	if runtime.GOOS != "windows" {
		signals = append(signals, syscall.SIGTERM)
	}
	signal.Notify(sigChan, signals...)
	go func() {
		// First signal: cancel the context so in-flight work unwinds
		// cleanly. signal.Notify has disabled Go's default "signal
		// terminates" behavior, so without the second read below a user
		// who Ctrl-C's again during a slow/stuck shutdown (e.g. a keyring
		// read blocked in a subprocess we can't cancel) would find every
		// further Ctrl-C swallowed. The second read restores an escape
		// hatch: signal again to force-exit.
		//
		// We remember which signal fired so the eventual termination
		// re-raises that same signal â€” a SIGTERM (from a supervisor /
		// container stop) must exit 143, not masquerade as a SIGINT 130.
		sig := <-sigChan
		procsignal.Store(sig)
		if sig == os.Interrupt {
			fmt.Fprintln(os.Stderr, "\nInterruptingâ€¦ press Ctrl-C again to force quit.")
		} else {
			fmt.Fprintln(os.Stderr, "\nReceived termination signal, shutting downâ€¦ signal again to force quit.")
		}
		cancel()
		<-sigChan
		dieFromSignal(sig)
	}()

	// Create and execute root command
	rootCmd := cli.NewRootCmd()

	// Make managed-installed plugins discoverable by the kubectl-style
	// dispatcher: prepend the managed bin dir to PATH before resolution.
	// Idempotent and silent on failure (managed installs simply won't be
	// found this run; PATH-installed plugins still work). The closure
	// restores PATH so built-in commands and their subprocesses don't
	// inherit the prepended dir. When a plugin runs, we skip the restore
	// â€” the os.Exit ends the process, and the plugin child intentionally
	// inherits the prepended PATH so it can spawn sibling managed plugins.
	restorePATH := cli.PrependPluginBinDirToPATH(ctx)

	if handled, code := cli.MaybeRunPlugin(ctx, rootCmd, os.Args[1:]); handled {
		cancel()
		os.Exit(code)
	}
	restorePATH()

	// Retired env vars fail every built-in command up front; a removed knob
	// must never be silently ignored. Plugins (above) are exempt â€” what they
	// read is their business.
	if err := api.RejectRemovedAuthEnv(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		cancel()
		os.Exit(1)
	}

	executed, err := rootCmd.ExecuteContextC(ctx)
	// The only place the logger is closed, and it must be here: cobra returns out
	// of Command.execute() as soon as RunE errors or required-flag validation
	// fails, both before its PersistentPostRun loop, so those paths would
	// otherwise exit with up to 8KB of buffered diagnostics unwritten. The logger
	// rides the executed command's context, where the root pre-run put it; a
	// failure raised before any pre-run carries none, and nothing logged yet.
	if l := logging.LoggerFromContext(executed.Context()); l != nil {
		_ = l.Close()
	}

	if err != nil {
		var silent *cli.SilentError

		switch {
		case errors.Is(err, context.Canceled) && procsignal.Load() != nil:
			// A signal cancelled the root context (our handler fired) or a
			// keyring read was aborted by Ctrl-C. Don't dump the raw
			// transport/keyring cancellation string ("...: context canceled",
			// "read access token: signal: interrupt") as if it were a failure
			// â€” die quietly by re-raising the signal that triggered it (see
			// dieFromSignal) so an enclosing `while ...; do entire; done` loop
			// actually breaks on a single Ctrl-C, and a SIGTERM shutdown still
			// exits 143.
			//
			// We gate on a signal having been recorded rather than on the
			// error type alone: a context.Canceled that arose without a signal
			// (e.g. an internally-cancelled sub-context) is a genuine error
			// and must fall through to normal reporting, not masquerade as a
			// user abort (which would also wrongly break an enclosing loop).
			// procsignal is the shared source of truth written both by the
			// handler above and by the keyring interrupt path; the latter
			// records the signal on this same goroutine before returning, so
			// this Load never races that write.
			cancel()
			dieFromSignal(terminatingSignal())
		case errors.As(err, &silent):
			// Command already printed the error
		case strings.Contains(err.Error(), "unknown command") || strings.Contains(err.Error(), "unknown flag"):
			showSuggestion(rootCmd, err)
		case isPositionalArgError(err):
			// Arg-count errors come from cobra's own validators (e.g.
			// cobra.ExactArgs) and surface as "accepts N arg(s), received M".
			// Show the failing subcommand's usage so the user sees what it
			// actually expects â€” rootCmd's usage isn't useful for a
			// subcommand-level arg mismatch. ExecuteContextC returns the
			// deepest matched command, which is the one that failed.
			showSuggestion(executed, err)
		default:
			// The choke point for everything a command returns rather than
			// prints itself: see cli.RenderUserFacingError for what it strips
			// and which other render sites exist.
			fmt.Fprintln(rootCmd.OutOrStderr(), cli.RenderUserFacingError(err))
		}

		cancel()
		os.Exit(1)
	}
	if cli.ShouldCheckCheckpointPolicyWarning(executed) {
		cli.WarnCheckpointPolicyIfNeeded(ctx, rootCmd.ErrOrStderr(), versioninfo.Version)
	}
	cancel() // Cleanup on successful exit
}

// terminatingSignal returns the signal that cancelled the root context,
// defaulting to SIGINT when the cancellation came from something other than a
// recorded terminating signal (so a stray context.Canceled still exits 130).
// The recorded signal lives in the shared procsignal package, written by the
// handler goroutine (SIGINT/SIGTERM) and by the keyring interrupt path (SIGINT).
func terminatingSignal() os.Signal {
	if s := procsignal.Load(); s != nil {
		return s
	}
	return os.Interrupt
}

// dieFromSignal terminates the process as if it had been killed by sig, rather
// than exiting normally. The distinction matters to an interactive shell: it
// only aborts a `while true; do entire ...; done` loop when the child is
// *killed by* SIGINT (WIFSIGNALED). A plain os.Exit(130) is an ordinary exit,
// so the loop keeps respawning entire and Ctrl-C never escapes it. Re-raising
// the actual signal also keeps a SIGTERM shutdown reporting the conventional
// 143 (not 130). We reset sig to its default disposition, re-raise it to
// ourselves, and briefly wait for delivery; if the re-raise can't be delivered
// (e.g. Windows, where signal-to-self is unsupported) we fall back to a
// conventional 128+signal exit so we never hang.
func dieFromSignal(sig os.Signal) {
	signal.Reset(sig)
	if p, err := os.FindProcess(os.Getpid()); err == nil {
		if err := p.Signal(sig); err == nil {
			time.Sleep(500 * time.Millisecond) // signal delivery ends the process well before this elapses
		}
	}
	os.Exit(exitCodeForSignal(sig))
}

// exitCodeForSignal maps a signal to the conventional 128+signum exit code
// (130 for SIGINT, 143 for SIGTERM), falling back to 130 for a signal that
// doesn't carry a numeric value on this platform.
func exitCodeForSignal(sig os.Signal) int {
	if s, ok := sig.(syscall.Signal); ok {
		return 128 + int(s)
	}
	return 130
}

// isPositionalArgError reports whether err looks like a cobra positional-
// arg validator failure. cobra's stock validators (ExactArgs, NoArgs,
// MinimumNArgs, MaximumNArgs, RangeArgs) all surface error strings
// containing "arg(s)", and that substring doesn't appear in cobra's other
// error paths or in the cli's own errors â€” so it's a stable, cheap
// discriminator without reaching into cobra internals.
func isPositionalArgError(err error) bool {
	return strings.Contains(err.Error(), "arg(s)")
}

func showSuggestion(cmd *cobra.Command, err error) {
	// Print usage first (brew style)
	fmt.Fprint(cmd.OutOrStderr(), cmd.UsageString())
	fmt.Fprintf(cmd.OutOrStderr(), "\nError: Invalid usage: %v\n", err)
}

// Command git-remote-entire is the git remote helper for entire:// URLs.
//
// Git resolves `git clone entire://host/project/repo` by exec'ing a binary
// named git-remote-entire on PATH, handing it the remote-helper protocol on
// stdin and reading responses from stdout. This is a small, dedicated
// binary (no cobra command tree) that shares the protocol, transport, and
// auth packages with the main entire CLI.
//
// IMPORTANT: nothing here may write to stdout except the helper protocol
// itself â€” git parses stdout as a strict pkt-line stream, so a stray banner
// or log line corrupts the transfer. Diagnostics go to stderr (and the
// ENTIRE_DEBUG-gated debuglog).
//
// Authentication resolves the login context for the target cluster from the
// shared contexts.json: the cluster's cores come from the cluster_cores.json
// cache (or a live /.well-known fetch on miss), then the account is selected
// from local contexts. It uses that context's login JWT (or ENTIRE_TOKEN in
// CI) directly as the git-transport bearer.
package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"os/signal"
	"regexp"
	"runtime"
	"strings"
	"sync"
	"syscall"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/entireio/cli/internal/entireclient/clusterdiscovery"
	"github.com/entireio/cli/internal/entireclient/httpclient"
	"github.com/entireio/cli/internal/entireclient/httputil"
	"github.com/entireio/cli/internal/entireclient/userdirs"
	"github.com/entireio/cli/internal/remotehelper"
	"github.com/entireio/cli/internal/remotehelper/debuglog"
	"github.com/entireio/cli/internal/remotehelper/githelper"
	"github.com/entireio/cli/internal/remotehelper/httpdebug"
	"github.com/entireio/cli/internal/remotehelper/replicas"
	"github.com/entireio/cli/internal/remotehelper/transport"
)

func main() {
	os.Exit(run(os.Args))
}

func run(args []string) int {
	// --version / --help only activate as the sole argument (so os.Args has
	// length 2). Git always invokes the helper as
	// `git-remote-entire <remote-name> <url>` (os.Args length 3), so these can
	// never collide with a real remote-helper invocation.
	if len(args) == 2 {
		if text, ok := infoFlagText(args[1], loadedVersion()); ok {
			fmt.Fprint(os.Stdout, text)
			return 0
		}
	}

	if len(args) < 3 {
		fmt.Fprintf(os.Stderr, "usage: %s <remote-name> <url>\n", remotehelper.BinaryName)
		return 128
	}

	// Build info drives the identifier the helper advertises upstream.
	// One string covers both surfaces:
	//   - githelper.Agent rides in the git protocol pkt-line agent=
	//     capability appended to upload-pack / receive-pack / v2 requests.
	//   - httpUserAgent rides in the HTTP User-Agent header on every
	//     outbound request so server access logs can attribute traffic.
	// Using the same value keeps the two log surfaces correlatable.
	versioninfo.Load()
	helperAgent := remotehelper.BinaryName + "/" + versioninfo.Version
	githelper.Agent = helperAgent
	httpUserAgent := helperAgent

	rawURL := args[2]
	parsedURL, err := url.Parse(rawURL)
	switch {
	case err != nil:
		fmt.Fprintf(os.Stderr, "fatal: invalid URL %q: %v\n", rawURL, err)
		return 128
	case parsedURL.Scheme != "entire":
		fmt.Fprintf(os.Stderr, "fatal: unsupported URL scheme %q (expected 'entire')\n", parsedURL.Scheme)
		return 128
	case parsedURL.Host == "" || gitremote.IsForgePathToken(parsedURL.Host):
		// Cluster host absent (empty, or a forge id in its slot);
		// missingClusterHostMessage renders the actionable hint.
		fmt.Fprint(os.Stderr, missingClusterHostMessage(parsedURL, rawURL))
		return 128
	}

	ctx, stop := installSignals()
	defer stop()

	skipTLS := os.Getenv("ENTIRE_TLS_SKIP_VERIFY") == "true"

	nodeCfg := replicas.Resolve(parsedURL)

	// This client drives the auth path only: cluster /.well-known discovery
	// and the token exchange. Both talk to a single control-plane host with no
	// failover to fall back on, so they get the patient discovery dial budget
	// (DiscoveryDialTimeout, i.e. DefaultDiscoveryDialTimeout unless
	// ENTIRE_CONNECT_TIMEOUT_SECONDS overrides it) rather than the short failover
	// one â€” a slow cold connect here would otherwise fail the whole clone/fetch.
	httpClient := &http.Client{
		Timeout: 30 * time.Second,
		Transport: &httpclient.UserAgentTransport{
			Next: &httpdebug.TimingRoundTripper{
				Next:  httpclient.NewDiscoveryTransport(skipTLS),
				Label: "auth",
			},
			UA: httpUserAgent,
		},
	}

	creds, onUnauthorized, err := resolveCreds(ctx, parsedURL, skipTLS, httpClient)
	if err != nil {
		fmt.Fprintf(os.Stderr, "fatal: %v\n", err)
		return 128
	}

	setAuth := setAuthWithProvider(creds)

	var onNodeFailed func(string)
	if nodeCfg.Caching() {
		onNodeFailed = func(string) { replicas.Invalidate(nodeCfg.ClusterHost, nodeCfg.RepoPath) }
	}

	proxy := transport.New(transport.Config{
		Nodes:          nodeCfg,
		Path:           parsedURL.Path,
		SkipTLS:        skipTLS,
		SetAuth:        setAuth,
		OnUnauthorized: onUnauthorized,
		OnNodeFailed:   onNodeFailed,
		UserAgent:      httpUserAgent,
	})

	protocolVersion := resolveProtocolVersion()
	debuglog.Printf("git protocol.version=%d (v2 advertises stateless-connect + push; v0/v1 advertises connect)", protocolVersion)

	helperStart := time.Now()
	if err := githelper.Run(ctx, proxy, protocolVersion, os.Stdin, os.Stdout); err != nil {
		fmt.Fprint(os.Stderr, fatalMessage(err, parsedURL))
		return 128
	}
	debuglog.Printf("timing: helper-session dur_ms=%d", time.Since(helperStart).Milliseconds())
	return 0
}

type credentialProvider func(context.Context) (string, error)

type refreshableCredential interface {
	Token(ctx context.Context) (string, error)
	ForceRefresh(ctx context.Context, staleToken string) (string, error)
}

// refreshingProvider defers reactive refresh work until the transport rebuilds
// a request after a 401, so the network call uses that request's context. The
// observer itself only marks the last bearer stale.
func refreshingProvider(credential refreshableCredential) (credentialProvider, func()) {
	var mu sync.Mutex
	var lastToken, rejectedToken string

	provider := func(ctx context.Context) (string, error) {
		mu.Lock()
		stale := rejectedToken
		rejectedToken = ""
		mu.Unlock()

		var token string
		var err error
		if stale != "" {
			token, err = credential.ForceRefresh(ctx, stale)
		} else {
			token, err = credential.Token(ctx)
		}
		if err != nil {
			if stale != "" {
				mu.Lock()
				if rejectedToken == "" {
					rejectedToken = stale
				}
				mu.Unlock()
			}
			return "", fmt.Errorf("resolve login credential: %w", err)
		}

		mu.Lock()
		lastToken = token
		mu.Unlock()
		return token, nil
	}

	onUnauthorized := func() {
		mu.Lock()
		rejectedToken = lastToken
		mu.Unlock()
		debuglog.Printf("data plane rejected login bearer; marked it stale for the transport's retry")
	}
	return provider, onUnauthorized
}

func setAuthWithProvider(provider credentialProvider) transport.SetAuthFunc {
	return func(req *http.Request) error {
		// Refuse to attach credentials to a request we can't classify as a
		// known git smart-HTTP endpoint. Sending a bearer to an unexpected
		// endpoint is never right.
		if gitActionFromRequest(req) == "" {
			return fmt.Errorf("refusing to attach credentials: %s %s is not a recognised git smart-HTTP endpoint", req.Method, req.URL.Path)
		}
		token, err := provider(req.Context())
		if err != nil {
			return fmt.Errorf("resolve git credential: %w", err)
		}
		req.Header.Set("Authorization", "Bearer "+token)
		return nil
	}
}

// wrongClusterRe extracts the host that actually serves the repo from the
// data plane's `invalid_target` error_description (RFC 8693). The data plane
// emits this when the audience host doesn't host the repo but a sibling
// cluster does, naming the correct host so we can point the user at it. The
// phrasing is "â€¦ it lives on \"<host>\" â€¦"; anchoring on "lives on" keeps the
// match tied to this specific, actionable case rather than other
// invalid_target variants (e.g. a suspended mirror).
var wrongClusterRe = regexp.MustCompile(`lives on "([^"]+)"`)

// fatalMessage renders the stderr "fatal: â€¦" line for a transfer error. When
// the failure is the data plane reporting that the repo lives on a different
// cluster, it special-cases the raw OAuth chain into an actionable message
// naming the correct host (and the corrected entire:// URL). Everything else
// falls back to the verbatim error.
func fatalMessage(err error, parsedURL *url.URL) string {
	var oe *httputil.OAuthError
	if errors.As(err, &oe) && oe.Code == "invalid_target" {
		if m := wrongClusterRe.FindStringSubmatch(oe.Description); m != nil {
			host := m[1]
			// Copy the URL the user typed and swap only the host, so any
			// escaped path (RawPath) or query stays byte-identical to what
			// they originally ran.
			correctedURL := *parsedURL
			correctedURL.Scheme = "entire"
			correctedURL.Host = host
			correctedURL.User = nil
			corrected := correctedURL.String()
			return fmt.Sprintf("fatal: this repository is not hosted on %s; it lives on %s.\n"+
				"Re-run against the correct host, e.g.:\n\n    git clone %s\n",
				parsedURL.Host, host, corrected)
		}
	}
	return fmt.Sprintf("fatal: %v\n", err)
}

// missingClusterHostMessage renders the stderr "fatal: â€¦" line for an entire://
// URL that omits its cluster host. Two shapes reach here: a forge id typed
// where the host belongs (entire://gh/owner/repo, Host="gh") and an empty host
// (entire:///gh/owner/repo, Host=""). When the reconstructed shorthand is a
// complete forge/owner/repo triple that `entire repo clone` can resolve, it
// points at that command; a partial path (entire://gh, entire://gh/owner) or a
// non-forge segment falls back to the plain missing-host error rather than
// suggesting a clone command that would reject the ref. Kept pure so it's
// unit-testable.
//
// The trailing segments are labelled per forge (gitremote.ForgePathLabels), so
// a native path reads <project>/<repo> rather than a mirror's <owner>/<repo>.
// The suggestion stays neutral about what `repo clone` will then do â€” it
// prompts between clusters for a multi-cluster mirror, and goes straight to the
// home cluster for a native ref â€” because naming the mirror picker here was
// wrong for half the forges.
func missingClusterHostMessage(parsedURL *url.URL, rawURL string) string {
	// Reconstruct the forge/owner/repo shorthand the user likely intended: a
	// forge id in the host slot sits in front of the path; an empty host
	// already has it there.
	shorthand := strings.TrimPrefix(parsedURL.Path, "/")
	if parsedURL.Host != "" {
		shorthand = parsedURL.Host + "/" + shorthand
	}
	// Only point at `entire repo clone` for a complete forge/owner/repo triple
	// (the shape parseMirrorCloneRef accepts); anything shorter would relocate
	// the failure into a clone command that rejects the ref.
	seg := strings.Split(strings.Trim(shorthand, "/"), "/")
	if len(seg) != 3 || seg[0] == "" || seg[1] == "" || seg[2] == "" || !gitremote.IsForgePathToken(seg[0]) {
		return fmt.Sprintf("fatal: missing host in URL %q\n", rawURL)
	}
	return fmt.Sprintf(
		"fatal: entire:// URL is missing its cluster host (%q is a forge id, not a host).\n"+
			"The full form is entire://<cluster-host>/%s/%s.\n"+
			"To clone it, run:\n\n    entire repo clone /%s\n",
